<?php $e = static fn (mixed $value): string => App\Core\View::e($value); ?>
<article class="public-news-detail"><p class="eyebrow"><?= $e($article['championship_name']) ?></p><h1><?= $e($article['title']) ?></h1><p class="news-byline">Publicado em <?= $e($article['published_at']) ?> por <?= $e($article['author_name']) ?></p><?php if (!empty($article['cover_image_path'])): ?><img class="news-cover" src="<?= $e(App\Core\Config::url('/campeonatos/' . $article['championship_slug'] . '/noticias/' . $article['slug'] . '/capa')) ?>" alt="Capa: <?= $e($article['title']) ?>"><?php endif; ?><p class="news-summary"><?= $e($article['summary']) ?></p><div class="news-content"><?= nl2br($e($article['content'])) ?></div><p><a href="<?= $e(App\Core\Config::url('/campeonatos/' . $article['championship_slug'] . '/noticias')) ?>">Voltar para noticias</a></p></article>
